// Utilization index computed dynamically, never hardcoded: (demandShare x serviceTime / doctors), normalized to General OPD = 1.00
export function utilizationIndex(dept) {
  const raw = (d) => (d.demandShare * d.serviceTime) / d.doctors;
  const baseline = raw(DEPARTMENTS[0]);
  return raw(dept) / baseline;
}

